# REF-MergeWriterAudit-Build.ps1 - builds the TEMPORARY "who writes DisableLocalAdminMerge" audit (POAM-046, 21 Oct 2026).
# Writes REF-MergeWriterAudit-Detect.ps1 and -Remediate.ps1 next to this file from ONE core.
#
# WHY. DISA V-278656 reads HKLM\SOFTWARE\Policies\Microsoft\Windows Defender\DisableLocalAdminMerge = 1. Every tenant writer sets 1
# (DefenderAV-STIG ADMX, STIG Registry Closure), yet the value keeps returning to 0 - at boot and between boots - on both PCs.
# Ruled out 21 Oct: tenant policies, REF remediations, local Group Policy, the ADMX mapping. Security Officer: "do this now".
# WHAT. Registry auditing is already on in the tenant (REF-AuditPolicy-AU: Object Access > Audit Registry = Success and
# Failure). This adds ONE audit entry (SACL) to that single key - Everyone, SetValue + Delete, success, this key only - so
# Windows writes Security event 4657 naming the PROCESS, account, old and new value each time a value in it is changed.
# Mode Audit (v1): SYSTEM, hourly. Detect: SACL present? collect every 4657 for that key (48 h) into
#   C:\ProgramData\REF\MergeWriterAudit.txt and the Intune output; exit 1 only when the SACL is missing (remediate adds it).
#   A write to 0 also goes to the REF event log (event 4401).
# Mode Remove: takes the audit entry off again (rebuild with -Mode Remove, push with REF-Update-Remediation.ps1), then
# unassign. No setting, value, permission (DACL) or service is changed in either mode.
# Get-Acl -Audit / Set-Acl enable SeSecurityPrivilege themselves; a raw OpenSubKey with ACCESS_SYSTEM_SECURITY would need it enabled
# by hand, and compiled Add-Type helpers are not an option under App Control.
# WORST CASE: a few extra Security events per hour. WAY BACK: Mode Remove; or unassign (the SACL alone is harmless).
param([ValidateSet('Audit', 'Remove')][string]$Mode = 'Audit')
$ErrorActionPreference = 'Stop'
$here = Split-Path -Parent $MyInvocation.MyCommand.Path

$core = @'
# REF Merge-Writer Audit core v1 (21 Oct 2026, POAM-046). Generated by REF-MergeWriterAudit-Build.ps1 - do not edit by hand.
$ErrorActionPreference = 'Continue'
$sub = 'SOFTWARE\Policies\Microsoft\Windows Defender'; $path = "HKLM:\$sub"; $out = 'C:\ProgramData\REF\MergeWriterAudit.txt'
$everyone = New-Object System.Security.Principal.SecurityIdentifier 'S-1-1-0'
$rights = [System.Security.AccessControl.RegistryRights]'SetValue, Delete'
function Our-Rules($acl) { @($acl.GetAuditRules($true, $false, [System.Security.Principal.SecurityIdentifier]) | Where-Object { $_.IdentityReference -eq $everyone -and (($_.RegistryRights -band $rights) -eq $rights) }) }
try { $have = @(Our-Rules (Get-Acl -Path $path -Audit -ErrorAction Stop)).Count -gt 0 } catch { $have = $false }
# --- findings: every 4657 for this key in 48 h
$rows = @(); try { foreach ($e in @(Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 4657; StartTime = (Get-Date).AddHours(-48) } -ErrorAction Stop)) {
        $x = [xml]$e.ToXml(); $d = @{}; foreach ($n in $x.Event.EventData.Data) { $d[$n.Name] = $n.'#text' }
        if ($d.ObjectName -notmatch 'Policies\\Microsoft\\Windows Defender$') { continue }
        $rows += "{0:yyyy-MM-dd HH:mm:ss} | {1} | {2} -> {3} | process {4} (pid {5}) | account {6}\{7} | op {8}" -f $e.TimeCreated, $d.ObjectValueName, $d.OldValue, $d.NewValue, $d.ProcessName, $d.ProcessId, $d.SubjectDomainName, $d.SubjectUserName, $d.OperationType } } catch { }
$zero = @($rows | Where-Object { $_ -match '\| DisableLocalAdminMerge \| \S* -> (0|0x0|0x00000000) \|' })
$cur = (Get-ItemProperty $path -ErrorAction SilentlyContinue).DisableLocalAdminMerge
try { New-Item -ItemType Directory -Force -Path (Split-Path $out) | Out-Null; @("REF Merge-Writer Audit ($Mode) on $env:COMPUTERNAME, $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss zzz') | SACL present: $have | value now: $cur | events (48 h): $($rows.Count)") + $rows | Set-Content $out -Encoding UTF8 } catch { }
if ($zero) { try { if (-not [Diagnostics.EventLog]::SourceExists('REF-MergeWriterAudit')) { New-EventLog -LogName REF -Source 'REF-MergeWriterAudit' }; Write-EventLog -LogName REF -Source 'REF-MergeWriterAudit' -EventId 4401 -EntryType Warning -Message ("DisableLocalAdminMerge set to 0 by:`n" + ($zero -join "`n")) } catch { } }
$sum = "value now $cur | SACL $(if ($have) { 'ON' } else { 'OFF' }) | writes 48 h: $($rows.Count) | to 0: $(if ($zero) { ($zero | Select-Object -Last 3) -join ' ;; ' } else { 'none yet' })"
if ($Mode -eq 'Detect-Audit') { Write-Output "Merge-Writer Audit: $sum"; if ($have) { exit 0 } else { exit 1 } }
if ($Mode -eq 'Detect-Remove') { Write-Output "Merge-Writer Audit (removing): $sum"; if ($have) { exit 1 } else { exit 0 } }
# --- remediate
try {
    $acl = Get-Acl -Path $path -Audit -ErrorAction Stop
    if ($Mode -eq 'Remediate-Audit' -and -not (Our-Rules $acl)) { $acl.AddAuditRule((New-Object System.Security.AccessControl.RegistryAuditRule($everyone, $rights, 'None', 'None', 'Success'))); Set-Acl -Path $path -AclObject $acl -ErrorAction Stop; Write-Output "Merge-Writer Audit: SACL added (Everyone, SetValue+Delete, success) | $sum"; exit 0 }
    if ($Mode -eq 'Remediate-Remove') { foreach ($r in @(Our-Rules $acl)) { [void]$acl.RemoveAuditRuleSpecific($r) }; Set-Acl -Path $path -AclObject $acl -ErrorAction Stop; Write-Output "Merge-Writer Audit: SACL removed | $sum"; exit 0 }
    Write-Output "Merge-Writer Audit: nothing to do | $sum"; exit 0
} catch { Write-Output "Merge-Writer Audit: FAILED $($_.Exception.Message) | $sum"; exit 1 }
'@

$hdr = "# Built $(Get-Date -Format 'yyyy-MM-dd HH:mm') by REF-MergeWriterAudit-Build.ps1 (mode $Mode)`r`n"
[IO.File]::WriteAllText((Join-Path $here 'REF-MergeWriterAudit-Detect.ps1'), $hdr + "`$Mode = 'Detect-$Mode'`r`n" + $core, (New-Object Text.UTF8Encoding $true))
[IO.File]::WriteAllText((Join-Path $here 'REF-MergeWriterAudit-Remediate.ps1'), $hdr + "`$Mode = 'Remediate-$Mode'`r`n" + $core, (New-Object Text.UTF8Encoding $true))
Get-ChildItem $here -Filter 'REF-MergeWriterAudit-*.ps1' | ForEach-Object { "{0}  {1} bytes  SHA256 {2}" -f $_.Name, $_.Length, (Get-FileHash $_.FullName).Hash.Substring(0, 8) }
